`IEnumerable<T>` 和 `IQueryable<T>` 的差异不在于接口签名，而在于**查询在哪儿执行**。

**IEnumerable<T>**
- `Where` 接收的是 `Func<T, bool>` —— 一个 IL 编译后的委托
- 每次调用 `MoveNext()` 时，元素被拉到客户端内存里，执行委托做过滤
- 即「客户端评估」：数据全部或分批进入内存后，过滤/排序/投影都在进程内完成

**IQueryable<T>**
- `Where` 接收的是 `Expression<Func<T, bool>>` —— 表达式树，不是委托
- 表达式树描述的是查询的语法结构（比较、字段名、常量），EF Core 的查询提供程序遍历这棵树，翻译成目标数据源的查询语言（SQL）
- 即「服务端评估」：过滤条件进 WHERE 子句、排序进 ORDER BY、投影进 SELECT 列表，只有命中的行返回客户端

```csharp
// 全部加载到内存再过滤 → SELECT * FROM Students
IEnumerable<Student> seq = dbContext.Students.AsEnumerable();
var adults = seq.Where(s => s.Age >= 18);

// 表达式树 → SELECT * FROM Students WHERE Age >= 18
IQueryable<Student> q = dbContext.Students;
var adults2 = q.Where(s => s.Age >= 18);
```

关键原则：**在 IQueryable 链条上，只要操作符是 EF Core 能翻译的，查询就在数据库执行**。但链条一旦「落地」——调用 `ToList()`、`AsEnumerable()`、`AsQueryable()`（这个只是表面返回 IQueryable，底层数据已经在内存）——后续操作就在客户端执行。

一条经验判断：如果一个自定义方法内部调用了数据库不支持的 C# 逻辑（比如正则、复杂计算），放在 IQueryable 的 Where/Select 里会导致 EF 抛异常（翻译失败）或客户端评估（取决于 EF 版本和配置）。正确做法是先过滤可翻译的部分（在数据库执行），再 ToList 后做内存中的额外处理。

using System;
using System.Collections.Generic;
using System.Linq;

namespace LinqDemo
{
    public class Student
    {
        public int Id { get; set; }
        public string Name { get; set; } = "";
        public int Age { get; set; }
        public string City { get; set; } = "";
        public List<int> Scores { get; set; } = new();
    }

    class Program
    {
        static void Main()
        {
            var students = new List<Student>
            {
                new() { Id = 1, Name = "Alice",   Age = 20, City = "Beijing",   Scores = new() { 85, 90, 78 } },
                new() { Id = 2, Name = "Bob",     Age = 22, City = "Shanghai",  Scores = new() { 92, 88, 95 } },
                new() { Id = 3, Name = "Charlie", Age = 19, City = "Beijing",   Scores = new() { 76, 82, 80 } },
                new() { Id = 4, Name = "David",   Age = 21, City = "Guangzhou", Scores = new() { 90, 85, 88 } },
                new() { Id = 5, Name = "Eve",     Age = 23, City = "Shanghai",  Scores = new() { 95, 92, 98 } }
            };

            // === 1. 延迟执行演示 ===
            Console.WriteLine("=== 延迟执行 ===");
            var deferredQuery = students.Where(s =>
            {
                Console.WriteLine($"  Evaluating {s.Name} (Age={s.Age})");
                return s.Age > 20;
            });

            Console.WriteLine("Query created (no iteration yet).");
            Console.WriteLine("First iteration:");
            foreach (var s in deferredQuery) { Console.WriteLine($"  -> {s.Name}"); }

            Console.WriteLine("Second iteration (re-executes!):");
            foreach (var s in deferredQuery) { Console.WriteLine($"  -> {s.Name}"); }

            // === 2. 物化避免重复执行 ===
            Console.WriteLine("\n=== ToList 物化 ===");
            var materialized = students.Where(s => s.Age > 20).ToList(); // 遍历一次，结果缓存
            foreach (var s in materialized) { Console.WriteLine($"  {s.Name}"); }
            foreach (var s in materialized) { Console.WriteLine($"  {s.Name} (no re-evaluation)"); }

            // === 3. 查询语法 vs 方法语法 (编译后等价) ===
            Console.WriteLine("\n=== 两种语法等价 ===");
            var querySyntax = from s in students
                              where s.Age >= 20
                              orderby s.Name
                              select new { s.Name, s.Age };

            var methodSyntax = students
                .Where(s => s.Age >= 20)
                .OrderBy(s => s.Name)
                .Select(s => new { s.Name, s.Age });

            // 两种结果完全一致
            Console.WriteLine($"  Same result: {querySyntax.SequenceEqual(methodSyntax)}");

            // === 4. GroupBy + 聚合 ===
            Console.WriteLine("\n=== GroupBy ===");
            var grouped = students
                .GroupBy(s => s.City)
                .Select(g => new { City = g.Key, Count = g.Count(), AvgAge = g.Average(s => s.Age) });

            foreach (var g in grouped)
            {
                Console.WriteLine($"  {g.City}: {g.Count} students, avg age {g.AvgAge:F1}");
            }

            // === 5. SelectMany 展开嵌套 ===
            Console.WriteLine("\n=== SelectMany ===");
            var allScores = students
                .SelectMany(s => s.Scores.Select(score => new { s.Name, score }))
                .OrderByDescending(x => x.score);

            foreach (var item in allScores)
            {
                Console.WriteLine($"  {item.Name}: {item.score}");
            }

            // === 6. 闭包捕获变量延迟读取 ===
            Console.WriteLine("\n=== 闭包与延迟执行 ===");
            int threshold = 10;
            var closureQuery = students.Where(s => s.Age > threshold);
            threshold = 25; // 修改捕获的变量
            Console.WriteLine($"  threshold changed to {threshold} before iteration:");
            foreach (var s in closureQuery)\            {
                Console.WriteLine($"    {s.Name} (Age={s.Age})"); // 只有 Age > 25 的才会出现
            }

            // === 7. 量词操作符 (立即执行) ===
            Console.WriteLine("\n=== 量词 ===");
            var cities = new[] { "Beijing", "Shanghai" };
            bool anyInCities = students.Any(s => cities.Contains(s.City));
            bool allAdults = students.All(s => s.Age >= 18);
            Console.WriteLine($"  Any in [Beijing,Shanghai]: {anyInCities}");
            Console.WriteLine($"  All adults: {allAdults}");
        }
    }
}

